CREATE TABLE `operations_tasks` (`id` text PRIMARY KEY NOT NULL,`title` text NOT NULL,`description` text DEFAULT '' NOT NULL,`status` text DEFAULT 'OPEN' NOT NULL,`priority` text DEFAULT 'NORMAL' NOT NULL,`category` text DEFAULT 'GENERAL' NOT NULL,`assignee` text,`due_at` integer,`source_type` text,`source_id` text,`member_id` text,`created_by` text NOT NULL,`completed_at` integer,`created_at` integer NOT NULL,`updated_at` integer NOT NULL,FOREIGN KEY (`member_id`) REFERENCES `members`(`id`) ON UPDATE no action ON DELETE no action);
CREATE INDEX `operations_tasks_status_due_idx` ON `operations_tasks` (`status`,`due_at`);
CREATE INDEX `operations_tasks_source_idx` ON `operations_tasks` (`source_type`,`source_id`);
CREATE TABLE `member_tags` (`member_id` text NOT NULL,`tag` text NOT NULL,`source` text DEFAULT 'STAFF' NOT NULL,`created_by` text NOT NULL,`created_at` integer NOT NULL,FOREIGN KEY (`member_id`) REFERENCES `members`(`id`) ON UPDATE no action ON DELETE no action);
CREATE UNIQUE INDEX `member_tags_member_tag_unique` ON `member_tags` (`member_id`,`tag`);
CREATE INDEX `member_tags_tag_idx` ON `member_tags` (`tag`);
CREATE TABLE `admin_saved_filters` (`id` text PRIMARY KEY NOT NULL,`owner_email` text NOT NULL,`name` text NOT NULL,`scope` text DEFAULT 'MEMBERS' NOT NULL,`conditions_json` text DEFAULT '{}' NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE UNIQUE INDEX `admin_saved_filters_owner_name_unique` ON `admin_saved_filters` (`owner_email`,`scope`,`name`);
CREATE TABLE `coupons` (`id` text PRIMARY KEY NOT NULL,`name` text NOT NULL,`description` text DEFAULT '' NOT NULL,`status` text DEFAULT 'DRAFT' NOT NULL,`benefit_type` text NOT NULL,`benefit_value` integer DEFAULT 0 NOT NULL,`starts_at` integer,`ends_at` integer,`usage_limit` integer,`smaregi_coupon_id` text,`created_by` text NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE INDEX `coupons_status_period_idx` ON `coupons` (`status`,`starts_at`,`ends_at`);
CREATE TABLE `member_coupons` (`id` text PRIMARY KEY NOT NULL,`coupon_id` text NOT NULL,`member_id` text NOT NULL,`status` text DEFAULT 'HELD' NOT NULL,`issued_at` integer NOT NULL,`used_at` integer,`smaregi_transaction_id` text,FOREIGN KEY (`coupon_id`) REFERENCES `coupons`(`id`) ON UPDATE no action ON DELETE no action,FOREIGN KEY (`member_id`) REFERENCES `members`(`id`) ON UPDATE no action ON DELETE no action);
CREATE UNIQUE INDEX `member_coupons_coupon_member_unique` ON `member_coupons` (`coupon_id`,`member_id`);
CREATE INDEX `member_coupons_member_status_idx` ON `member_coupons` (`member_id`,`status`);
CREATE TABLE `surveys` (`id` text PRIMARY KEY NOT NULL,`title` text NOT NULL,`description` text DEFAULT '' NOT NULL,`status` text DEFAULT 'DRAFT' NOT NULL,`questions_json` text DEFAULT '[]' NOT NULL,`reward_points` integer DEFAULT 0 NOT NULL,`created_by` text NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE TABLE `survey_responses` (`id` text PRIMARY KEY NOT NULL,`survey_id` text NOT NULL,`member_id` text,`answers_json` text DEFAULT '{}' NOT NULL,`reward_status` text DEFAULT 'NONE' NOT NULL,`submitted_at` integer NOT NULL,FOREIGN KEY (`survey_id`) REFERENCES `surveys`(`id`) ON UPDATE no action ON DELETE no action,FOREIGN KEY (`member_id`) REFERENCES `members`(`id`) ON UPDATE no action ON DELETE no action);
CREATE INDEX `survey_responses_survey_idx` ON `survey_responses` (`survey_id`,`submitted_at`);
CREATE TABLE `message_campaigns` (`id` text PRIMARY KEY NOT NULL,`name` text NOT NULL,`status` text DEFAULT 'DRAFT' NOT NULL,`channel` text DEFAULT 'CARD' NOT NULL,`audience_json` text DEFAULT '{}' NOT NULL,`content_json` text DEFAULT '{}' NOT NULL,`scheduled_at` integer,`sent_at` integer,`created_by` text NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
CREATE INDEX `message_campaigns_status_schedule_idx` ON `message_campaigns` (`status`,`scheduled_at`);
CREATE TABLE `automation_rules` (`id` text PRIMARY KEY NOT NULL,`name` text NOT NULL,`trigger_type` text NOT NULL,`enabled` integer DEFAULT 0 NOT NULL,`conditions_json` text DEFAULT '{}' NOT NULL,`action_json` text DEFAULT '{}' NOT NULL,`last_run_at` integer,`created_by` text NOT NULL,`created_at` integer NOT NULL,`updated_at` integer NOT NULL);
